CREATE TABLE "ProductoCategoriaComercial" (
  "id" UUID NOT NULL,
  "codigo" TEXT NOT NULL,
  "nombre" TEXT NOT NULL,
  "descripcion" TEXT,
  "orden" INTEGER NOT NULL DEFAULT 0,
  "activo" BOOLEAN NOT NULL DEFAULT true,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

  CONSTRAINT "ProductoCategoriaComercial_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "ProductoSubcategoriaComercial" (
  "id" UUID NOT NULL,
  "categoriaId" UUID NOT NULL,
  "codigo" TEXT NOT NULL,
  "nombre" TEXT NOT NULL,
  "descripcion" TEXT,
  "atributosSchemaJson" JSONB NOT NULL,
  "orden" INTEGER NOT NULL DEFAULT 0,
  "activo" BOOLEAN NOT NULL DEFAULT true,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

  CONSTRAINT "ProductoSubcategoriaComercial_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "ProductoCategoriaComercial_codigo_key"
  ON "ProductoCategoriaComercial"("codigo");
CREATE INDEX "ProductoCategoriaComercial_activo_orden_idx"
  ON "ProductoCategoriaComercial"("activo", "orden");
CREATE UNIQUE INDEX "ProductoSubcategoriaComercial_codigo_key"
  ON "ProductoSubcategoriaComercial"("codigo");
CREATE UNIQUE INDEX "ProductoSubcategoriaComercial_categoriaId_codigo_key"
  ON "ProductoSubcategoriaComercial"("categoriaId", "codigo");
CREATE INDEX "ProductoSubcategoriaComercial_categoriaId_activo_orden_idx"
  ON "ProductoSubcategoriaComercial"("categoriaId", "activo", "orden");

ALTER TABLE "ProductoSubcategoriaComercial"
  ADD CONSTRAINT "ProductoSubcategoriaComercial_categoriaId_fkey"
  FOREIGN KEY ("categoriaId") REFERENCES "ProductoCategoriaComercial"("id")
  ON DELETE RESTRICT ON UPDATE CASCADE;

