ALTER TABLE "Producto"
  ADD COLUMN "subcategoriaComercialId" UUID,
  ADD COLUMN "atributosComercialesJson" JSONB;

UPDATE "Producto"
SET "subcategoriaComercialId" = (SELECT "id" FROM "ProductoSubcategoriaComercial" WHERE "codigo" = 'tarjetas')
WHERE "codigo" = 'TARJ-PREMIUM-300';

UPDATE "Producto"
SET "subcategoriaComercialId" = (SELECT "id" FROM "ProductoSubcategoriaComercial" WHERE "codigo" = 'vinilos_impresos')
WHERE "codigo" = 'VINILO-BLANCO-IMP';

UPDATE "Producto"
SET "subcategoriaComercialId" = (SELECT "id" FROM "ProductoSubcategoriaComercial" WHERE "codigo" = 'talonarios')
WHERE "codigo" = 'TALON-DUPL-A4';

UPDATE "Producto"
SET "subcategoriaComercialId" = (SELECT "id" FROM "ProductoSubcategoriaComercial" WHERE "codigo" = 'rigidos_impresos')
WHERE "codigo" = 'RIGIDO-CUSTOM';

UPDATE "Producto"
SET "subcategoriaComercialId" = (SELECT "id" FROM "ProductoSubcategoriaComercial" WHERE "codigo" = 'producto_a_medida')
WHERE "subcategoriaComercialId" IS NULL;

ALTER TABLE "Producto"
  ALTER COLUMN "subcategoriaComercialId" SET NOT NULL;

ALTER TABLE "Producto"
  ADD CONSTRAINT "Producto_subcategoriaComercialId_fkey"
  FOREIGN KEY ("subcategoriaComercialId") REFERENCES "ProductoSubcategoriaComercial"("id")
  ON DELETE RESTRICT ON UPDATE CASCADE;

CREATE INDEX "Producto_subcategoriaComercialId_idx"
  ON "Producto"("subcategoriaComercialId");
